// Anti-aliased bitmap fonts for the tile menu: 4-bit coverage, two pixels per byte.
// The font data itself is generated by tools/make_menu_fonts.py into menu_fonts.h.
#pragma once

#include <cstdint>

namespace omenu {

struct Glyph {
    uint32_t offset; // Index of the glyph's first pixel in the font's packed bits.
    uint8_t width, height;
    int8_t x, y;     // Bitmap position from the pen: x across, y down from the line's top.
    uint8_t advance; // Pen movement after this glyph.
};

struct Font {
    const Glyph *glyphs;
    const uint8_t *bits;
    uint8_t first, last; // Character codes covered.
    uint8_t ascent, descent;
};

} // namespace omenu
